def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    from_style = self.SQLParams.in_style
    to_style = self.SQLParams.out_style

    if from_style == 'named':
        param_placeholder = ':'
        if to_style == 'pyformat':
            to_placeholder = '%('
            suffix = ')s'
        elif to_style == 'qmark':
            to_placeholder = '?'
            suffix = ''
        else:
            raise ValueError(f"Unsupported out-style: {to_style}")

        if sql.startswith(b'%'):
            sql = sql.decode()

        def convert_named_params(params):
            converted_params = []
            if to_placeholder == '%(':
                converted_sql = sql
                for i, param in enumerate(params):
                    new_params = {}
                    for key, value in param.items():
                        new_key = f'{to_placeholder}{key}{suffix}'
                        converted_sql = converted_sql.replace(f'{param_placeholder}{key}', new_key)
                        new_params[key] = value
                    converted_params.append(new_params)
            elif to_placeholder == '?':
                converted_sql = sql
                param_mapping = {}
                for i, param in enumerate(params):
                    for key, value in param.items():
                        if key not in param_mapping:
                            param_mapping[key] = len(param_mapping) + 1
                        converted_sql = converted_sql.replace(f'{param_placeholder}{key}', f'{to_placeholder}')
                    converted_params.append([param[key] for key in sorted(param, key=lambda x: param_mapping[x])])
            return converted_sql, converted_params

        formatted_sql, out_params = convert_named_params(many_params)

    elif from_style in ('qmark', 'numeric', 'format', 'pyformat'):
        if from_style == 'qmark':
            from_placeholder = '?'
        elif from_style == 'numeric':
            from_placeholder = ':'
        elif from_style == 'format':
            from_placeholder = '%'
        elif from_style == 'pyformat':
            from_placeholder = '%('

        if to_style == 'named':
            param_placeholder = ':'
            to_placeholder = '%('
            suffix = ')s'
        elif to_style == 'qmark':
            to_placeholder = '?'
            suffix = ''
        else:
            raise ValueError(f"Unsupported out-style: {to_style}")

        def convert_from_params(params):
            converted_params = []
            if to_placeholder == '%(':
                param_count = 1
                converted_sql = sql
                for i, param in enumerate(params):
                    new_params = {}
                    for j, value in enumerate(param):
                        key = f'param{param_count}'
                        converted_sql = converted_sql.replace(from_placeholder, f'{to_placeholder}{key}{suffix}', 1)
                        new_params[key] = value
                        param_count += 1
                    converted_params.append(new_params)
            elif to_placeholder == '?':
                converted_sql = sql
                converted_params = [list(param) for param in params]
            return converted_sql, converted_params

        formatted_sql, out_params = convert_from_params(many_params)

    else:
        raise ValueError(f"Unsupported in-style: {from_style}")

    return formatted_sql, out_params

