def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = [indent_str + "Object: " + self.__class__.__name__]
    if debug:
        parts.append(indent_str + "Address: " + hex(id(self)))
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple)):
            parts.append(indent_str + f"{key}:")
            for item in value:
                parts.append(self._pretty_item(item, indent + 2, debug))
        elif isinstance(value, dict):
            parts.append(indent_str + f"{key}:")
            for sub_key, sub_value in value.items():
                parts.append(self._pretty_item({sub_key: sub_value}, indent + 2, debug))
        else:
            parts.append(self._pretty_item({key: value}, indent + 2, debug))
    return '\n'.join(parts)

