def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from itertools import combinations

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|' and left == right[1]:
                    return left
                if isinstance(right, tuple) and right[0] == '|' and left == right[2]:
                    return left
                if isinstance(left, tuple) and left[0] == '|' and left[1] == right:
                    return right
                if isinstance(left, tuple) and left[0] == '|' and left[2] == right:
                    return right
            if op == '|':
                if isinstance(right, tuple) and right[0] == '&' and left == right[1]:
                    return left
                if isinstance(right, tuple) and right[0] == '&' and left == right[2]:
                    return left
                if isinstance(left, tuple) and left[0] == '&' and left[1] == right:
                    return right
                if isinstance(left, tuple) and left[0] == '&' and left[2] == right:
                    return right
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|' and right[1] == ('~', left):
                    return (op, left, right[2])
                if isinstance(right, tuple) and right[0] == '|' and right[2] == ('~', left):
                    return (op, left, right[1])
            if op == '|':
                if isinstance(right, tuple) and right[0] == '&' and right[1] == ('~', left):
                    return (op, left, right[2])
                if isinstance(right, tuple) and right[0] == '&' and right[2] == ('~', left):
                    return (op, left, right[1])
        return expr

    new_args = []
    for expr in args:
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        new_args.append(expr)

    # Check for further simplifications
    for i, j in combinations(range(len(new_args)), 2):
        new_args[i] = apply_absorption((new_args[i], '&', new_args[j]))
        new_args[j] = apply_absorption((new_args[j], '&', new_args[i]))
        new_args[i] = apply_absorption((new_args[i], '|', new_args[j]))
        new_args[j] = apply_absorption((new_args[j], '|', new_args[i]))
        new_args[i] = apply_negative_absorption((new_args[i], '&', new_args[j]))
        new_args[j] = apply_negative_absorption((new_args[j], '&', new_args[i]))
        new_args[i] = apply_negative_absorption((new_args[i], '|', new_args[j]))
        new_args[j] = apply_negative_absorption((new_args[j], '|', new_args[i]))

    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from itertools import combinations

    def apply_absorption(expr1, expr2):
        if isinstance(expr1, tuple) and isinstance(expr2, tuple):
            op1, a1, b1 = expr1
            op2, a2, b2 = expr2
            if op1 == '&' and op2 == '|':
                if a1 == a2:
                    return a1
                if a1 == ~b2 or b1 == ~a2:
                    return (op1, a1, b2 if a1 == ~b2 else a2)
            elif op1 == '|' and op2 == '&':
                if a1 == a2:
                    return a1
                if a1 == ~b2 or b1 == ~a2:
                    return (op2, a1, b2 if a1 == ~b2 else a2)
        return None

    result = args[:]
    for i, j in combinations(range(len(args)), 2):
        expr1, expr2 = result[i], result[j]
        new_expr = apply_absorption(expr1, expr2)
        if new_expr:
            result = [x for k, x in enumerate(result) if k not in (i, j)]
            result.append(new_expr)
            return self.absorb(result)  # Recursively simplify

    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for i, expr in enumerate(args):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, a, b = expr
            if op == '&':
                if b == (('|', a, 'B') or ('|', 'B', a)):
                    new_args.append(a)
                elif b == (('&', ('~', a), 'B') or ('&', 'B', ('~', a))):
