    '''
    from collections import defaultdict

    def merge_values(v1, v2):
        if isinstance(v1, ruamel.yaml.nodes.MappingNode) and isinstance(v2, ruamel.yaml.nodes.MappingNode):
            merged_value = defaultdict(list)
            for k, v in v1.value:
                merged_value[k].append(v)
