def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return alphabet[0] if padding is None or padding == 0 else alphabet[0] * padding

    base = len(alphabet)
    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None:
        while len(digits) < padding:
            digits.append(alphabet[0])

    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must be non-empty")
    base = len(alphabet)
    if number == 0:
        result = alphabet[0]
    else:
        result = []
        while number > 0:
            number, digit = divmod(number, base)
            result.append(alphabet[digit])
        result.reverse()
        result = ''.join(result)
    if padding is not None:
        result = result.zfill(padding)
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    base = len(alphabet)
    result = []

    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    if padding:
