    """Call the given command(s)."""
    import subprocess
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise TypeError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise TypeError("args must be a list of strings")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running: {' '.join(full_command)}")
        stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        output = subprocess.check_output(full_command, cwd=cwd, env=env, stderr=stderr, text=True)
        if verbose:
            print(f"Output: {output}")
        return output
    except subprocess.CalledProcessError as e:
