def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    command = [commands] + args
    stdout = None
    stderr = None

    if verbose:
        stdout = subprocess.PIPE
        stderr = subprocess.STDOUT if hide_stderr else subprocess.PIPE

    try:
        process = subprocess.Popen(command, cwd=cwd, env=env, stdout=stdout, stderr=stderr, text=True)
        output, error_output = process.communicate()

        if verbose:
            if output:
                print(output, end='')
            if error_output:
                print(error_output, end='', file=sys.stderr)

        if process.returncode != 0:
            raise subprocess.CalledProcessError(returncode=process.returncode, cmd=command, output=output, stderr=error_output)

        return output if verbose else process.returncode

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error executing command: {e}", file=sys.stderr)
        raise

