def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    nodes_with_parents = set()
    for subject, predicate, obj in graph:
        if predicate == prop:
            nodes_with_parents.add(subject)
            if obj not in nodes_with_parents:
                roots.add(obj)
            if obj in roots:
                roots.remove(obj)
    all_nodes = set(graph.subjects()) | set(graph.objects())
    roots.update(all_nodes - nodes_with_parents)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    for subj, pred, obj in graph:
        if pred == prop:
            if subj not in graph.objects(predicate=prop):
                roots.add(subj)

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set(graph.subjects())

    for _, _, parent in graph.triples((None, prop, None)):
        if parent in roots:
            roots.remove(parent)

    return roots

