def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import json
    import os

    configurations = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                       msg=f"Configuration file {filename} does not exist.", args=(), exc_info=None)
            log_records.append(record)
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
            configurations[filename] = config

        except json.JSONDecodeError as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                       msg=f"Failed to parse JSON in {filename}: {str(e)}", args=(), exc_info=None)
            log_records.append(record)

    if overrides:
        for key, value in overrides.items():
            for config in configurations.values():
                config[key] = value

    if resolve_env:
        for config in configurations.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
                    env_var = value[2:-1]
                    env_value = os.getenv(env_var)
                    if env_value is not None:
                        config[key] = env_value
                    else:
                        record = logging.LogRecord(name='config_loader', level=logging.WARNING, pathname='environment',
                                                   lineno=0, msg=f"Environment variable {env_var} not found.", args=(), exc_info=None)
                        log_records.append(record)

    return configurations, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import json
    from dotenv import resolve_variables
    from jsonschema import validate, ValidationError

    configurations = {}
    errors = []

    def custom_log_error(message, filename):
        record = logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0, msg=message, args=(), exc_info=False)
        errors.append(record)

    schema = {
        "type": "object",
        # Define your schema here
    }

    for filename in config_filenames:
        if not os.path.exists(filename):
            custom_log_error(f"File not found: {filename}", filename)
            continue

        try:
            with open(filename, 'r') as file:
                config_data = json.load(file)

            if resolve_env:
                config_data = resolve_variables(config_data)

            if overrides:
                config_data.update(overrides)

            validate(instance=config_data, schema=schema)
            configurations[filename] = config_data

        except json.JSONDecodeError as e:
            custom_log_error(f"Error decoding JSON from {filename}: {e}", filename)
        except ValidationError as e:
            custom_log_error(f"Validation error in {filename}: {e}", filename)

    return configurations, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import toml
    import os

    configurations = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname='', lineno=0, msg=f'Configuration file not found: {filename}', args=(), exc_info=None))
            continue

        try:
            with open(filename, 'r') as file:
                config = toml.load(file)
                configurations[filename] = config
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname='', lineno=0, msg=f'Failed to parse configuration file {filename}: {str(e)}', args=(), exc_info=None))

    if overrides:
        for key, value in overrides.items():
            for config in configurations.values():
                config[key] = value

    if resolve_env:
        import re
        env_var_pattern = re.compile(r'\$\{([^}]+)\}')

        for filename, config in configurations.items():
            if isinstance(config, dict):
                for key, value in config.items():
                    if isinstance(value, str):
                        match = env_var_pattern.search(value)
                        if match:
                            env_var_name = match.group(1)
                            env_value = os.getenv(env_var_name)
                            if env_value is not None:
                                config[key] = env_var_pattern.sub(env_value, value)
                            else:
                                log_records.append(logging.LogRecord(name='config_loader', level=logging.WARNING, pathname='', lineno=0, msg=f'Environment variable {env_var_name} not found in {filename}', args=(), exc_info=None))

    return configurations, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
