        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(record)

    if overrides:
        for key, value in overrides.items():
            paths = key.split('.')
            target = config_dict
            for p in paths[:-1]:
                if p not in target:
                    target[p] = {}
                target = target[p]
            target[paths[-1]] = value

    if resolve_env:
        for filename, config in config_dict.items():
            try:
