def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        # Assuming JSON format follows Diaspora's new webfinger specification
        return data
    except json.JSONDecodeError:
        # Fallback to parsing XRD format (XML)
        try:
            root = ET.fromstring(document)
            data = {}
            for elem in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                rel = elem.get('rel')
                href = elem.get('href')
                if rel and href:
                    data[rel] = href
            return data
        except ET.ParseError:
            logger.warning("Failed to parse webfinger document as both JSON and XRD.")
            return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse the document as JSON
        data = json.loads(document)
        hcard_url = data['links'][0]['href']
        return {'hcard_url': hcard_url}
    except (json.JSONDecodeError, KeyError, IndexError):
        # If JSON parsing fails, try to parse it as XRD
        try:
            root = ET.fromstring(document)
            hcard_url = root.find(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link[@rel='http://microformats.org/profile/hcard']").attrib['href']
            return {'hcard_url': hcard_url}
        except (ET.ParseError, AttributeError, KeyError):
            # If both parsing attempts fail, return None
            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON
        data = json.loads(document)
        return {
            "handle": data.get("subject"),
            "hcard_url": next((l["href"] for l in data.get("links", []) if l.get("rel") == "http://microformats.org/profile/hcard"), None)
        }
    except json.JSONDecodeError:
        # Fallback to parsing as XRD
        root = etree.fromstring(document)
        handle = root.find(f"{{{XRD_NS}}}Subject").text
        hcard_url = root.find(f".//{{{XRD_NS}}}Link[@rel='http://microformats.org/profile/hcard']/{{{XRD_NS}}}Template").text
        if hcard_url:
            hcard_url = hcard_url.replace("{uri}", quote(handle))
        return {
            "handle": handle,
            "hcard_url": hcard_url
        }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Attempt to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If not valid JSON, try parsing as XML XRD
        try:
            root = ElementTree.fromstring(document)
            links = root.findall('.//{' + XRD_NS + '}Link')
            result = {}
            for link in links:
                attrs = link.attrib
                if 'rel' in attrs and 'href' in attrs:
                    result[attrs['rel']] = attrs['href']
            return result
        except ElementTree.ParseError:
            # If both parsing attempts fail, return an empty dictionary or handle the error
            return {}

