    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    parser = self.parsers[parser_name]
    for arg in parser._actions:
        if arg.dest in values_dict:
            try:
                values_dict[arg.dest] = arg.type(values_dict[arg.dest])
            except (ValueError, TypeError):
                # If conversion fails, keep the original value or use default
                values_dict[arg.dest] = values_dict.get(arg.dest, arg.default)

